{
  "units": [
    {
      "quote": "A material discrepancy is any name change that is not defined as immaterial in 8 FAM 403.1-5.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "A material discrepancy is defined as any name change that is not classified as immaterial under 8 FAM 403.1-5."
    },
    {
      "quote": "The applicant must explain any material discrepancies between the name on the application and the name recorded in the evidence of U.S. citizenship/non-citizen U.S. nationality and the evidence of identity (see 22 CFR 51.25).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "An applicant is obligated to explain any material discrepancies existing between the name stated on their application and the name appearing on their evidence of U.S. citizenship or non-citizen U.S. nationality and their identity evidence."
    },
    {
      "quote": "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section (see an exception for married names in 8 FAM 403.1-4(C)).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Material discrepancies among the name on the application, evidence of U.S. citizenship/non-citizen U.S. nationality, or evidence of identity must be documented by submitting one or more of the documents specified in this section, subject to an exception for married names in 8 FAM 403.1-4(C)."
    },
    {
      "quote": "Court orders or decrees:\n\n(a) Name change orders; or\n\n(b) Divorce decrees;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Per 22 CFR 51.25, acceptable means to document a material name change include court orders or decrees, specifically name change orders or divorce decrees."
    },
    {
      "quote": "Certificates of naturalization;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Per 22 CFR 51.25, certificates of naturalization serve as an acceptable means of documenting a material name change."
    },
    {
      "quote": "Marriage certificates;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Per 22 CFR 51.25, marriage certificates serve as an acceptable means of documenting a material name change."
    },
    {
      "quote": "Documentation demonstrating change of name by operation of state law; or",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Per 22 CFR 51.25, documentation showing that a name change occurred by operation of state law is an acceptable means of documenting a material name change."
    },
    {
      "quote": "Documentation of customary usage.",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Per 22 CFR 51.25, documentation of customary usage is an acceptable means of documenting a material name change."
    },
    {
      "quote": "Evidence of material name changes must be reviewed for evidence of counterfeiting or alteration (see 8 FAM 201.1)",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Passport personnel must review submitted evidence of material name changes to check for counterfeiting or alteration."
    },
    {
      "quote": "The applicant may not continue to use a previous name after a material name change unless the name change documentation specifically permits the applicant to continue using that name (see 8 FAM 403.1-6 regarding “known as” names).",
      "scope_quotes": [],
      "kind": "prohibition",
      "meaning": "An applicant is prohibited from continuing to use a previous name following a material name change, except when the name change documentation explicitly authorizes continued use of that name."
    },
    {
      "quote": "under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:",
      "scope_quotes": [
        "The applicant's name is an integral part of her/his identity."
      ],
      "kind": "condition",
      "meaning": "In accordance with Department guidance under 22 CFR 51.23(c), evidence of identity may potentially be required to establish the name that best identifies the applicant."
    },
    {
      "quote": "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name.",
      "scope_quotes": [
        "under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:"
      ],
      "kind": "requirement",
      "meaning": "If an applicant underwent a material name change more than one year before submitting form DS-11 and has not updated their ID to reflect it, the adjudicator must suspend the application and request an acceptable ID showing the new name."
    },
    {
      "quote": "If there is insufficient time to request that the applicant submit acceptable ID prior to urgent or emergency travel, a limited-validity passport may be issued in the requested name;",
      "scope_quotes": [
        "under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:",
        "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name."
      ],
      "kind": "permission",
      "meaning": "When an applicant with a material name change older than one year lacks an updated ID, but urgent or emergency travel does not allow enough time to request acceptable ID, issuing a limited-validity passport in the requested name is permitted."
    },
    {
      "quote": "The applicant generally will need the name change documentation to change the name on her/his ID.",
      "scope_quotes": [
        "under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:"
      ],
      "kind": "statement",
      "meaning": "It is generally expected that the applicant will require their name change documentation in order to update the name on their ID."
    },
    {
      "quote": "You must fully notate the name change documentation prior to returning the documentation, including that the documentation was \"seen and returned,\" to the applicant with the information request letter (IRL);",
      "scope_quotes": [
        "under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:"
      ],
      "kind": "requirement",
      "meaning": "Before returning the name change documentation to the applicant alongside an Information Request Letter (IRL), personnel must fully notate the documentation, including recording that it was 'seen and returned'."
    },
    {
      "quote": "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name.",
      "scope_quotes": [
        "under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:"
      ],
      "kind": "exemption",
      "meaning": "Applicants whose material name change took place within one year of submitting form DS-11 are exempt from the requirement to submit an ID displaying the new name."
    },
    {
      "quote": "However, if the ID has not yet been changed, they must submit their name change documentation.",
      "scope_quotes": [
        "under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:",
        "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name."
      ],
      "kind": "requirement",
      "meaning": "Applicants who had a material name change within one year of applying on form DS-11 and whose ID has not yet been changed must submit their name change documentation."
    }
  ]
}

